const setContractStatus = `-- name: SetContractStatus :one
UPDATE contracts SET
    status = $1::text,
    status_before_approval = CASE WHEN $1::text = 'PENDING_APPROVAL'
                                  THEN status_before_approval ELSE '' END,
    signed_at = CASE WHEN $1::text = 'EFFECTIVE' AND signed_at IS NULL
                     THEN now() ELSE signed_at END,
    effective_at = CASE WHEN $1::text = 'EFFECTIVE' AND effective_at IS NULL
                        THEN now() ELSE effective_at END,
    completed_at = CASE WHEN $1::text = 'COMPLETED'
                        THEN now() ELSE completed_at END,
    updated_at = now(), updated_by = $2::bigint
WHERE tenant_id = $3::bigint AND id = $4::bigint
RETURNING status
`

type SetContractStatusParams struct {
	NewStatus string
	UpdatedBy int64
	TenantID  int64
	ID        int64
}

func (q *Queries) SetContractStatus(ctx context.Context, arg SetContractStatusParams) (string, error) {
	row := q.db.QueryRow(ctx, setContractStatus,
		arg.NewStatus,
		arg.UpdatedBy,
		arg.TenantID,
		arg.ID,
	)
	var status string
	err := row.Scan(&status)
	return status, err
}

